import type { AnalysisMode, ResumeParseStatus } from '../../types';

export interface ReportFixtureInput {
  mode: AnalysisMode;
  result: string;
  fileName: string | null;
  createdAt: string | null;
  resumeFileName?: string | null;
  resumeParseStatus?: ResumeParseStatus | null;
}

const dimension = (index: number, name: string, score: string) => `### ${index}. ${name}

- **评分**: ${score}
- **STAR 证据**：候选人先明确目标与约束，再通过访谈、数据和小范围验证识别关键问题，并推动相关团队在既定时间内完成交付。
- **行为观察**：回答能够区分背景、个人判断、具体行动和最终结果，信息结构完整，关键取舍有事实支撑。
- **风险提示**：部分结果仍以区间描述，指标口径与个人贡献边界需要在后续环节继续核实。
- **建议追问**：如果核心指标连续两个周期没有改善，会优先检查哪些假设，何时决定停止投入。
- **判断依据**：案例与岗位要求相关，多个行为证据能够相互印证。
`;

const recruiterCore = `## 0. 候选人基础概览

- 候选人具备多年复杂业务产品和跨团队项目经验，经历覆盖需求洞察、方案设计、项目推进与结果复盘。
- 当前职业选择更关注业务空间、团队成熟度以及长期能力积累。

## 1. 综合匹配结论

- **匹配结论**: H
- **主要优势**：表达结构清楚，能够说明决策依据、关键约束与取舍逻辑，并对结果指标保持持续关注。
- **主要风险**：部分案例量化不充分，个人贡献与团队共同成果之间的边界需要进一步澄清。
- **后续建议**：补充追问关键指标口径、反事实比较，以及重大分歧中的真实影响方式。

## 2. 核心能力概览

- **业务理解**：能够识别增长、效率和体验之间的核心矛盾，并结合用户反馈与经营数据判断优先级。
- **产品判断**：能够把长期方向拆成短周期验证，清楚区分事实、假设和待验证风险。
- **项目推进**：跨团队沟通主动，能识别依赖关系并设计里程碑，在变化中维持交付节奏。
- **数据意识**：习惯定义目标指标和过程指标，对复杂实验设计仍需更多证据。

## 3. 指定维度详细评估

${dimension(1, '需求及业务理解', 'H')}
${dimension(2, '方案设计与产品判断', 'H')}
${dimension(3, '数据分析与验证', 'H-')}
${dimension(4, '项目管理与执行', 'H+')}
${dimension(5, '沟通协作与影响力', 'H')}
${dimension(6, '用户洞察与体验意识', 'H')}
${dimension(7, '复盘学习与成长性', 'H-')}

## 4. 亮点、风险与待验证事项

- **亮点一**：能够将复杂问题结构化，并持续把讨论拉回目标、事实和约束。
- **亮点二**：推进意识强，善于识别关键路径并通过机制减少跨团队等待。
- **风险一**：结果量化不够一致，需要核实指标口径以及对结果的真实贡献。
- **待验证**：技术复杂度判断、实验设计能力、团队培养经验与长期战略思考。

## 5. 最终建议

- 建议进入下一轮，下一轮以事实核验和风险验证为主，不重复宽泛经历介绍。
- 由业务负责人深挖一个成功案例和一个失败案例，要求明确目标口径、替代方案、个人决策和可验证结果。
`;

const paddingSentences = [
  '补充观察：候选人能够在信息不完整时先建立假设清单，并用低成本动作减少关键不确定性。',
  '补充观察：面对目标变化时能够重新确认优先级，同时向相关团队解释范围调整和交付影响。',
  '补充观察：多数案例能够说明个人动作，但仍需核实最终结果是否具有持续性和可复制性。',
  '补充观察：报告保留真实长度和段落密度，用于验证标题跟随、列表分页和长文字换行。',
];

const buildRecruiterResult = () => {
  let result = recruiterCore;
  let index = 0;
  while (result.length < 3588) {
    const sentence = `\n- ${paddingSentences[index % paddingSentences.length]}`;
    result += sentence.slice(0, 3588 - result.length);
    index += 1;
  }
  return result;
};

export const recruiterFixture: ReportFixtureInput = {
  mode: 'recruiter',
  result: buildRecruiterResult(),
  fileName: '匿名面试记录.txt',
  createdAt: '2026-08-03T08:00:00.000Z',
};

export const candidateFixture: ReportFixtureInput = {
  mode: 'candidate',
  fileName: '匿名复盘记录.txt',
  createdAt: '2026-08-03T08:00:00.000Z',
  resumeFileName: '匿名简历.pdf',
  resumeParseStatus: 'usable',
  result: `## 本场表现结论

**一句话总结：** 本场表达结构基本清楚，但关键结果和个人贡献还可以说得更具体。

**本场重点：** 值得保留的做法 2 项、核心改进问题 3 项，最优先改进的是量化结果表达。

**下次准备：** 提前准备两个带完整指标口径的 STAR 案例，并明确个人决策与团队贡献边界。

## 值得保留的做法

- **先澄清问题**：面对宽泛问题时先确认目标、范围和关键约束。
- **表达有结构**：能够按照背景、行动和结果组织主要信息。

## 最需要改进的核心问题

### 1. 量化结果不足
- **问题表现**：多次使用明显改善等模糊表述，没有给出统一指标。
- **原因分析**：准备案例时更关注过程，没有提前整理结果口径。
- **示范回答**：项目上线后核心路径完成率从匿名基线提升到匿名目标，观察周期为四周。

### 2. 个人贡献边界模糊
- **问题表现**：团队动作较完整，但个人做出的关键判断不够突出。
- **原因分析**：习惯使用我们作为主语，忽略了面试官需要判断个人能力。
- **示范回答**：我负责提出替代方案、组织评审并推动关键负责人完成决策。

### 3. 失败复盘不够深入
- **问题表现**：能够说明结果不及预期，但没有解释当时为何做出错误判断。
- **原因分析**：复盘集中在流程动作，没有深入识别认知偏差。
- **示范回答**：我当时过早相信高意向用户反馈，忽略了普通用户样本不足的风险。

## 下一次面试准备清单

1. 为两个核心案例补齐目标、基线、结果和观察周期。
2. 将团队动作改写为个人判断、个人行动和协同动作。
3. 准备一个失败案例，说明错误假设、识别信号和后续改变。
`,
};

export const longParagraphFixture: ReportFixtureInput = {
  ...recruiterFixture,
  result: `${recruiterFixture.result}\n\n${'这是一段用于验证跨页文字换行的匿名长段落。'.repeat(120)}`,
};

